SELECT COALESCE(sub0.time, sub1.time) AS "time", (sub0.value - lag(sub0.value) OVER (ORDER BY sub0.time)) AS "sensor.ENERGY.Total", (sub1.value) AS "sensor.ENERGY.Total" FROM (SELECT time_bucket('1d', "time", 'Europe/Berlin') AS "time", last("sensor.ENERGY.Total", "time") AS value FROM "device:reH7pvpfRwSZl4HcFo9i9A_service:l4BYIMoKRsWdzxbC44awUA" WHERE "time" > now() - interval '8d' GROUP BY 1 ORDER BY 1 ASC LIMIT 9) sub0 FULL OUTER JOIN (SELECT time_bucket('1d', "time", 'Europe/Berlin') AS "time", avg("sensor.ENERGY.Total") AS value FROM "device:reH7pvpfRwSZl4HcFo9i9A_service:l4BYIMoKRsWdzxbC44awUA" WHERE "time" > now() - interval '8d' GROUP BY 1 ORDER BY 1 ASC LIMIT 9) sub1 on sub0.time = sub1.time ORDER BY 1 DESC LIMIT 7